// Clone returns an independent copy of the stream at the same bar: the two
// evolve separately and share only the [Core].
func (sp *CDL3WHITESOLDIERSStream) Clone() *CDL3WHITESOLDIERSStream {
	cl := *sp
	cl.ring_BodyShortTrailingIdx_derived = append(sp.ring_BodyShortTrailingIdx_derived[:0:0], sp.ring_BodyShortTrailingIdx_derived...)
	cl.ring_FarTrailingIdx_derived = append(sp.ring_FarTrailingIdx_derived[:0:0], sp.ring_FarTrailingIdx_derived...)
	cl.ring_NearTrailingIdx_derived = append(sp.ring_NearTrailingIdx_derived[:0:0], sp.ring_NearTrailingIdx_derived...)
	cl.ring_ShadowVeryShortTrailingIdx_derived = append(sp.ring_ShadowVeryShortTrailingIdx_derived[:0:0], sp.ring_ShadowVeryShortTrailingIdx_derived...)
	return &cl
}

